const b = $input.first().json.body || $input.first().json || {};
const op = (b.action || b.op || '').toString();
if (!['bot_on', 'bot_off', 'close', 'reopen', 'mark_read', 'delete_message', 'delete'].includes(op)) throw new Error('unknown action');
const id = parseInt(b.conversationId || b.id) || 0;
if (!id) throw new Error('missing conversation');
const mid = parseInt(b.messageId) || 0;
if (op === 'delete_message' && !mid) throw new Error('missing message');
let sql = '';
if (op === 'bot_on' || op === 'bot_off') {
  const v = op === 'bot_on' ? 1 : 0;
  const txt = op === 'bot_on' ? 'เปิดให้บอทตอบห้องนี้อีกครั้ง' : 'ปิดบอทห้องนี้ — พนักงานดูแลเอง';
  sql = `WITH u AS (UPDATE cd_conversations SET bot_enabled = ${v} WHERE id = ${id} RETURNING 1), ins AS (INSERT INTO cd_messages (conversation_id, sender, content, message_type, status) SELECT ${id}, 'system', '${txt}', 'text', 'ok' WHERE EXISTS (SELECT 1 FROM u) RETURNING 1) SELECT EXISTS(SELECT 1 FROM cd_conversations WHERE id = ${id}) AS found`;
} else if (op === 'close' || op === 'reopen') {
  const st = op === 'close' ? 'closed' : 'open';
  const txt = op === 'close' ? 'ปิดเคสนี้แล้ว' : 'เปิดเคสนี้ขึ้นมาใหม่';
  const extra = op === 'close' ? ', unread_count = 0' : '';
  sql = `WITH u AS (UPDATE cd_conversations SET status = '${st}'${extra} WHERE id = ${id} RETURNING 1), ins AS (INSERT INTO cd_messages (conversation_id, sender, content, message_type, status) SELECT ${id}, 'system', '${txt}', 'text', 'ok' WHERE EXISTS (SELECT 1 FROM u) RETURNING 1) SELECT EXISTS(SELECT 1 FROM cd_conversations WHERE id = ${id}) AS found`;
} else if (op === 'mark_read') {
  sql = `WITH a AS (UPDATE cd_conversations SET unread_count = 0 WHERE id = ${id} AND unread_count > 0 RETURNING 1), b AS (UPDATE cd_messages SET read_at = COALESCE(read_at, NOW()) WHERE conversation_id = ${id} AND sender = 'customer' AND read_at IS NULL RETURNING 1) SELECT EXISTS(SELECT 1 FROM cd_conversations WHERE id = ${id}) AS found`;
} else if (op === 'delete_message') {
  sql = `WITH d AS (DELETE FROM cd_messages WHERE id = ${mid} AND conversation_id = ${id} AND sender IN ('bot', 'agent') RETURNING 1) SELECT (SELECT COUNT(*) FROM d) AS deleted, EXISTS(SELECT 1 FROM cd_conversations WHERE id = ${id}) AS found`;
} else if (op === 'delete') {
  sql = `WITH d AS (DELETE FROM cd_conversations WHERE id = ${id} RETURNING 1) SELECT (SELECT COUNT(*) FROM d) AS deleted`;
}
return [{ json: { op: op, id: id, mid: mid, sql: sql } }];

const t = $('Build SQL').first().json;
const op = t.op || '';
const r = $input.first().json;
const found = !(r.found === false || r.found === 0 || r.found === '0' || r.found === null || r.found === undefined);
const delN = parseInt(r.deleted) || 0;
const missing = { ok: false, error: 'ไม่พบห้องแชทนี้' };
if (op === 'delete_message') {
  if (!found && delN === 0) return [{ json: missing }];
  if (delN === 0) return [{ json: { ok: false, error: 'ลบข้อความนี้ไม่ได้ (ลบได้เฉพาะข้อความของบอทหรือเจ้าหน้าที่)' } }];
  return [{ json: { ok: true, deleted: true, messageId: t.mid, message: 'ลบข้อความแล้ว' } }];
}
if (op === 'delete') {
  if (delN === 0) return [{ json: missing }];
  return [{ json: { ok: true, deleted: true, message: 'ลบห้องแชทนี้แล้ว' } }];
}
if (!found) return [{ json: missing }];
if (op === 'bot_on') return [{ json: { ok: true, botEnabled: true, message: 'บอทกลับมาตอบห้องนี้แล้ว' } }];
if (op === 'bot_off') return [{ json: { ok: true, botEnabled: false, message: 'ปิดบอทแล้ว พนักงานดูแลเอง' } }];
if (op === 'close') return [{ json: { ok: true, status: 'closed', message: 'ปิดเคสแล้ว' } }];
if (op === 'reopen') return [{ json: { ok: true, status: 'open', message: 'เปิดเคสใหม่แล้ว' } }];
return [{ json: { ok: true, message: 'ทำเครื่องหมายว่าอ่านแล้ว' } }];
